<script module lang="ts">
/**
 * A month grid for choosing a date (`design/components/calendar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/calendar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/date-picker'
import { useMachine } from '@zag-js/svelte'

import {
  agentDate,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/calendar.module.css'
import Button from './Button.svelte'

export type FirstDayOfWeek = NonNullable<CalendarProps['firstDayOfWeek']>

export type CalendarDate = zag.CalendarDate

export interface CalendarMessages {
  previousMonth: string
  nextMonth: string
}

export interface CalendarProps {
  /**
   * Names the calendar from outside, as DatePicker's popup does.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  defaultValue?: CalendarDate | null
  /**
   * Disables the whole grid.
   */
  disabled?: boolean
  /**
   * Overrides the locale's first day of the week.
   */
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  /**
   * Controlled month navigation, for apps that need it.
   */
  focusedValue?: CalendarDate
  /**
   * App policy, such as booked-out days. Unavailable is not the same as disabled.
   */
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Drives names, numbering and the week's first day. Defaults to the app's.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: CalendarMessages
  minValue?: CalendarDate
  onChange?: (value: CalendarDate | null) => void
  onFocusChange?: (date: CalendarDate) => void
  value?: CalendarDate | null
}
</script>

<script lang="ts">
let {
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  defaultValue,
  disabled = false,
  firstDayOfWeek,
  focusedValue,
  isDateUnavailable,
  locale,
  maxValue,
  messages,
  minValue,
  onChange,
  onFocusChange,
  value,
}: CalendarProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled }))
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
let browserLanguage = $state(undefined as string | undefined)
let travel = $state('next')
let shownMonth = $state('')
let monthButton = $state(false)
let root = $state<HTMLElement | null>(null)
const say = $derived(messages ?? { previousMonth: 'Previous month', nextMonth: 'Next month' })
const language = $derived(locale ?? browserLanguage ?? 'en-US')
const english = $derived(language.toLowerCase().startsWith('en'))
const zone = $derived(Intl.DateTimeFormat().resolvedOptions().timeZone)
const dayName = $derived((date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
  if (!english) return text
  const said = today
    ? selected
      ? `Today, ${text} selected`
      : `Today, ${text}`
    : selected
      ? `${text} selected`
      : text
  if (minValue !== undefined && date.compare(minValue) === 0) return `${said}, First available date`
  if (maxValue !== undefined && date.compare(maxValue) === 0) return `${said}, Last available date`
  return said
})
const documentDirection = useDirection(() => root)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      inline: true,
      locale: language,
      timeZone: zone,
      value: value === undefined ? undefined : value === null ? [] : [value],
      defaultValue: defaultValue == null ? undefined : [defaultValue],
      min: minValue,
      max: maxValue,
      focusedValue: focusedValue,
      startOfWeek: firstDayOfWeek,
      disabled: disabled,
      isDateUnavailable:
        isDateUnavailable === undefined
          ? undefined
          : (date) => isDateUnavailable?.(date as zag.CalendarDate) === true,
      onValueChange: (details) => {
        onChange?.((details.value[0] as zag.CalendarDate | undefined) ?? null)
      },
      onFocusChange: (details) => {
        onFocusChange?.(details.focusedValue as zag.CalendarDate)
      },
      onVisibleRangeChange: (details) => {
        ;((travel =
          shownMonth !== '' && details.visibleRange.start.toString() < shownMonth
            ? 'previous'
            : 'next'),
          (shownMonth = details.visibleRange.start.toString()))
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const named = $derived([ariaLabel, api.visibleRangeText.formatted].filter(Boolean).join(', '))
const monthButtonsOff = $derived(
  `${api.getPrevTriggerProps().disabled === true} ${api.getNextTriggerProps().disabled === true}`,
)
const dayOf = $derived((date: zag.DateValue) => {
  const cell = api.getDayTableCellState({ value: date })
  const off = disabled || cell.invalid
  const refused = isDateUnavailable?.(date as zag.CalendarDate) === true
  const selected = cell.selected && !off && !refused
  return {
    date,
    cell,
    off,
    unavailable: refused,
    outside: cell.outsideRange,
    selectable: !off && !refused,
    selected,
    name: dayName(date, cell.valueText, cell.today, selected),
  }
})
const weeks = $derived(api.weeks.map((week) => week.map((date) => dayOf(date))))
const effect1 = () => {
  browserLanguage = globalThis.navigator?.language
}
watchEffect(effect1)
const effect2 = () => {
  shownMonth = api.visibleRange.start.toString()
}
watchEffect(effect2)
const effect3 = () => {
  monthButton &&
    ((held) =>
      held === null || held === document.body || (held as HTMLButtonElement).disabled === true)(
      document.activeElement,
    ) &&
    ((monthButton = false),
    requestAnimationFrame(() =>
      root?.querySelector<HTMLElement>('[data-calendar-part="day"][tabindex="0"]')?.focus(),
    ))
}
watchEffect(effect3, { watch: () => monthButtonsOff, mount: false })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'Calendar',
    element: () => root,
    state: () => ({ value: api.value[0]?.toString() ?? '', disabled: disabled }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            const date = agentDate(value, {
              min: minValue,
              max: maxValue,
              unavailable: isDateUnavailable,
            })
            api.setValue([date])
            api.setFocusedValue(date)
          })(),
      },
    },
    withholds: () => root,
  })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    {...attributes(api.getContentProps())}
    class={styles.root}
    hidden={undefined}
    tabindex={(undefined) as never}
    data-state={undefined}
    role="application"
    aria-label={named}
    aria-labelledby={ariaLabelledby}
    data-member="calendar"
    ><div
      class={styles.header}
      onfocusin={() => { monthButton = true }}
      onfocusout={(event) => { monthButton = (event.target as HTMLButtonElement).disabled === true }}
      ><Button
        variant="ghost"
        tone="neutral"
        size="sm"
        iconOnly={true}
        icon="previous"
        label={say.previousMonth}
        disabled={api.getPrevTriggerProps().disabled === true}
        onClick={() => { api.goToPrev() }}
      /><span class={styles.title} aria-live="polite">{api.visibleRangeText.formatted}</span
      ><Button
        variant="ghost"
        tone="neutral"
        size="sm"
        iconOnly={true}
        icon="next"
        label={say.nextMonth}
        disabled={api.getNextTriggerProps().disabled === true}
        onClick={() => { api.goToNext() }}
    /></div
    >{#key api.visibleRange.start.toString()
      }<table
        {...attributes(api.getTableProps())}
        class={styles.grid}
        tabindex={(undefined) as never}
        aria-label={named}
        data-travel={travel}
        ><thead aria-hidden="true"
          ><tr
            >{#each api.weekDays as weekday (weekday.long)
              }<th scope="col" aria-label={weekday.long}
                ><span aria-hidden="true">{weekday.short}</span
              ></th
            >{/each
          }</tr
        ></thead
        ><tbody
          >{#each weeks as week, at (at)
            }<tr
              >{#each week as day (day.date.toString())
                }{#if day.outside
                  }<td></td
                >{:else
                  }<td
                    class={styles.cell}
                    role="gridcell"
                    aria-disabled={(!day.selectable) ? 'true' : undefined}
                    aria-selected={(day.selected) ? 'true' : undefined}
                    ><div
                      {...attributes(mergeParts(api.getDayTableCellTriggerProps({ value: day.date }), { onFocus: () => { api.setFocusedValue(day.date) }, onKeydown: (event: KeyboardEvent) => { if (event.key === ' ' && day.selectable) (event.preventDefault(), api.setValue([day.date])) } }))}
                      class={styles.day}
                      data-calendar-part="day"
                      aria-label={day.name}
                      aria-current={(day.cell.today) ? 'date' : undefined}
                      tabindex={(day.off ? undefined : day.cell.focused ? 0 : -1) as never}
                      data-selected={(day.selected) ? '' : undefined}
                      data-today={(day.cell.today) ? '' : undefined}
                      data-unavailable={(day.unavailable) ? '' : undefined}
                      data-disabled={(day.off) ? '' : undefined}
                      >{day.date.day
                    }</div
                  ></td
                >{/if
              }{/each
            }</tr
          >{/each
        }</tbody
      ></table
    >{/key
  }</div
>{/if
}{@render joined.end?.()}
